//! 🧪️ Exact Native metadata turns preserve original allocations and match the neutral independent output witnesses.
use super::*;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observed<T>(g:RetainedCloneGrant,operation:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result}
fn deny(d:RetirementDemand,mut operation:impl FnMut(RetainedCloneGrant)->RetainedCloneProgress){for axis in 0..5{let mut g=exact(d);let value=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *value==0{continue}*value-=1;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||operation(g));assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}
fn kind(name:&str)->LayoutExportKind{match name{"png"=>LayoutExportKind::Png,"svg"=>LayoutExportKind::Svg,"pdf"=>LayoutExportKind::Pdf,"step"=>LayoutExportKind::Step,"idml"=>LayoutExportKind::Idml,"package"=>LayoutExportKind::Package,_=>unreachable!()}}
fn oracle(name:&str)->(&'static str,&'static str,bool){match name{"png"=>("png","image/png",true),"svg"=>("svg","image/svg+xml",false),"pdf"=>("pdf","application/pdf",true),"step"=>("step","model/step",false),"idml"=>("idml","application/vnd.adobe.indesign-idml-package",true),"package"=>("layout-package.zip","application/zip",true),_=>unreachable!()}}
fn close(cursor:&mut LayoutExportMetadataCursor){cursor.begin_close();for _ in 0..100{if cursor.terminal_is_empty(){return}let d=cursor.close_demand();deny(d,|g|cursor.close_step(g).unwrap());observed(exact(d),||{let p=cursor.close_step(exact(d)).unwrap();((),p)});}panic!("original metadata backing did not close")}
fn run(laws:&serde_json::Value,row:&serde_json::Value,cut:Option<usize>){let base=&laws["base"];let page=row.get("pageId").unwrap_or(&base["pageId"]).as_str();let title=row["title"].as_str().unwrap_or(base["name"].as_str().unwrap());let document=row["documentId"].as_str().unwrap_or(base["documentId"].as_str().unwrap());let revision=std::array::from_fn(|at|u8::from_str_radix(&base["revision"].as_str().unwrap()[at*2..at*2+2],16).unwrap());let kind_name=row["kind"].as_str().unwrap();let input=LayoutExportMetadataInput{kind:kind(kind_name),name:title,page_id:page,document_id:document,revision:&revision};let mut cursor=observed(exact(LayoutExportMetadataCursor::birth_demand()),||LayoutExportMetadataCursor::admit(exact(LayoutExportMetadataCursor::birth_demand())).unwrap());let mut prepared=false;let mut failed=false;
 for _ in 0..cut.unwrap_or(10000){let d=cursor.next_demand(input).unwrap();deny(d,|g|cursor.advance(input,g).unwrap().progress);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(input,exact(d)));match result{Ok(step)=>{assert!(step.progress.fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));},Err(error)=>{assert!(error.retained_progress().fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));failed=true;break}}if cursor.ready(){let pointers=cursor.fields.each_ref().map(|field|field.as_ptr());let d=cursor.take_ready_demand();for axis in 0..3{let mut g=exact(d);match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes-=1,_=>g.maximum_depth-=1}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_ready(g));assert!(result.unwrap().is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let value=observed(exact(d),||{let(value,p)=cursor.take_ready(exact(d)).unwrap().unwrap();(value,p)});assert_eq!(value.parent_document_id,document);assert_eq!(value.page_id.as_deref(),page);assert_eq!(value.canonical_base_revision_hex,base["revision"].as_str().unwrap());let(ext,mime,binary)=oracle(kind_name);let name=if kind_name=="package"{title}else{page.unwrap_or(title)};let mut safe=name.chars().take(128).map(|character|if character.is_ascii_alphanumeric()||matches!(character,'.'|'_'|'-'){character}else{'-'}).collect::<String>();if safe.is_empty(){safe="layout".into()}assert_eq!(value.filename,format!("{safe}.{ext}"));assert_eq!(value.mime_type,mime);assert_eq!(value.encoding.as_deref(),binary.then_some("base64"));assert_eq!(value.parent_document_id.as_ptr(),pointers[1]);assert_eq!(value.filename.as_ptr(),pointers[3]);let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("same prepared String allocations"));while !owner.terminal_is_empty(){let d=owner.selected_demand(generous().maximum_copy_bytes).unwrap();observed(exact(d),||{let p=owner.step(exact(d)).unwrap().progress();((),p)});}prepared=true;break}}
 if cut.is_none(){assert_eq!(prepared,row["accept"].as_bool().unwrap_or(true),"{}",row["name"]);assert_eq!(failed,!prepared)}close(&mut cursor)}
#[test]fn exact_original_metadata_matches_neutral_outputs_and_physical_ownership(){let laws:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),16);for row in laws["cases"].as_array().unwrap(){run(&laws,row,None)}for cut in [0,1,2,3,10,32,64,100,200]{run(&laws,&laws["cases"][0],Some(cut))}}
#[test]fn changed_utf8_source_is_refused_before_owned_string_transfer(){let mut page=String::from("é");let revision=[31;32];let mut cursor=LayoutExportMetadataCursor::admit(generous()).unwrap().0;for _ in 0..100{let input=LayoutExportMetadataInput{kind:LayoutExportKind::Svg,name:"original",page_id:Some(&page),document_id:"original-layout",revision:&revision};let d=cursor.next_demand(input).unwrap();cursor.advance(input,exact(d)).unwrap();if cursor.field==0&&cursor.offset==1{break}}assert_eq!(cursor.offset,1);page.replace_range(..,"ab");for _ in 0..10000{let input=LayoutExportMetadataInput{kind:LayoutExportKind::Svg,name:"original",page_id:Some(&page),document_id:"original-layout",revision:&revision};let d=cursor.next_demand(input).unwrap();cursor.advance(input,exact(d)).unwrap();if cursor.ready(){break}}assert!(cursor.ready());let d=cursor.take_ready_demand();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_ready(exact(d)));let error=result.err().unwrap();assert_eq!(error.retained_progress().copied_bytes,d.copy_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close(&mut cursor)}
